source='''from collections import deque

def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = max(set(v for row in g for v in row), key=lambda v: sum(row.count(v) for row in g))
    seen = set()
    for r in range(h):
        for c in range(w):
            color = g[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and g[ny][nx] == color:
                        seen.add((ny,nx)); q.append((ny,nx))
            r0, r1 = min(y for y,x in cells), max(y for y,x in cells)
            c0, c1 = min(x for y,x in cells), max(x for y,x in cells)
            if r1-r0 < 2 or c1-c0 < 2:
                continue
            border = {(y,x) for y in range(r0,r1+1) for x in range(c0,c1+1)
                      if y in (r0,r1) or x in (c0,c1)}
            if set(cells) != border:
                continue
            interior_color = 2 if ((r1-r0-1) % 2 == 0) else 7
            for y in range(r0+1,r1):
                for x in range(c0+1,c1):
                    g[y][x] = interior_color
    return g
'''
